import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.Dxeykp0S.js";const k=JSON.parse('{"title":"Day 5 · Docker 化 Python 应用","description":"","frontmatter":{},"headers":[],"relativePath":"pro/05-dockerize.md","filePath":"pro/05-dockerize.md","lastUpdated":1787141678000}'),l={name:"pro/05-dockerize.md"};function r(s,e,d,n,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="day-5-·-docker-化-python-应用" tabindex="-1">Day 5 · Docker 化 Python 应用 <a class="header-anchor" href="#day-5-·-docker-化-python-应用" aria-label="Permalink to &quot;Day 5 · Docker 化 Python 应用&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Docker 化 Python 应用需要处理多阶段构建、依赖锁定、镜像最小化与非 root 运行。本课将重点处理 uv 的依赖安装方式，以及 gunicorn/uvicorn 这类 WSGI/ASGI 服务器的容器运行方式。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>写出生产级的 Python Dockerfile（多阶段构建）</li><li>掌握 uv 在容器内的最佳实践</li><li>镜像体积优化：slim / alpine 的取舍</li><li>掌握 Python 容器的健康检查与优雅退出</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.astral.sh/uv/guides/integration/docker/" target="_blank" rel="noreferrer">uv 官方：Docker 集成指南</a>（权威实践）</li><li><a href="https://docs.docker.com/language/python/" target="_blank" rel="noreferrer">Docker 官方：Python 镜像最佳实践</a></li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>Node Dockerfile 实践</th><th>Python 对应实践</th></tr></thead><tbody><tr><td><code>node:22-slim</code> 基础镜像</td><td><code>python:3.12-slim</code>（alpine 慎用，musl libc 编译坑多）</td></tr><tr><td><code>npm ci</code></td><td><code>uv sync --locked</code>（严格按 uv.lock 安装）</td></tr><tr><td>构建期 node_modules 不拷贝进最终镜像</td><td><code>.venv</code> 在多阶段间拷贝</td></tr><tr><td><code>node dist/server.js</code></td><td><code>uvicorn app:app --host 0.0.0.0</code></td></tr><tr><td>dumb-init / tini 处理信号</td><td>同样需要（Python 对 SIGTERM 的处理也要验证）</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><strong>多阶段 Dockerfile</strong>：为进阶班 Day 4 的 FastAPI 应用编写生产 Dockerfile：</li></ol><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 参考骨架，请完善细节</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ghcr.io/astral-sh/uv:python3.12-bookworm-slim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> builder</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... uv sync --locked --no-dev ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python:3.12-slim</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... 拷贝 .venv，非 root 用户，启动命令 ...</span></span></code></pre></div><p>要求：锁定依赖、不安装 dev 依赖、非 root 运行、启用 BuildKit 缓存挂载（<code>--mount=type=cache</code>）加速重复构建。</p><ol start="2"><li><p><strong>镜像体积优化</strong>：记录初始镜像大小，然后通过以下手段逐步优化并记录每一步的体积变化：</p><ul><li>slim 基础镜像</li><li>多阶段构建丢弃构建工具链</li><li><code>.dockerignore</code>（排除 <code>.venv</code>、<code>.git</code>、<code>tests</code>、<code>docs</code>）</li><li><code>--no-compile</code> 等 uv 优化选项</li></ul></li><li><p><strong>信号处理实验</strong>：在 FastAPI 应用中加入启动/关闭钩子（lifespan），打印日志。用 <code>docker stop</code> 观察应用是否优雅退出（收到 SIGTERM → 完成进行中请求 → 退出），对比 <code>PID 1</code> 问题：直接 <code>CMD [&quot;python&quot;, &quot;main.py&quot;]</code> vs exec 形式的差异。</p></li><li><p><strong>docker-compose 全家桶</strong>：写 <code>compose.yaml</code>：FastAPI 应用 + Redis + Postgres，应用通过环境变量连接，配置 healthcheck 与依赖顺序（<code>depends_on</code> + <code>condition: service_healthy</code>）。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>为什么 Python 镜像通常不选 alpine？（提示：manylinux wheel 与 musl）</li><li><code>.venv</code> 能从 builder 阶段直接拷贝到运行阶段吗？路径必须一致吗？</li><li><code>uv sync --locked</code> 和 <code>uv pip install -r requirements.txt</code> 在可复现性上有何差异？</li><li>为什么容器里要监听 <code>0.0.0.0</code> 而不是 <code>127.0.0.1</code>？</li><li>生产环境用 <code>uvicorn</code> 单进程还是 <code>gunicorn -k uvicorn.workers.UvicornWorker</code> 多进程？与 GIL 知识联系起来。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://pythonspeed.com/docker/" target="_blank" rel="noreferrer">Itamar Turner-Trauring: Python Docker 最佳实践系列</a></li><li><a href="https://github.com/GoogleContainerTools/distroless" target="_blank" rel="noreferrer">Distroless 镜像</a> —— 极致安全的最小镜像</li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节 <a href="./06-k8s-deploy">Day 6 · K8s 部署</a>：把容器编排起来，离毕业只差一步。</p>`,21)])])}const u=o(l,[["render",r]]);export{k as __pageData,u as default};
